<section class="panel no-print"><h2>Build your report</h2><p class="muted">Invoice reports filter by issue date. Collection reports filter by payment date. Class and student-type reports list the matching invoices.</p><form method="get" class="form-grid"><input type="hidden" name="page" value="reports"><?php selectField('type','Report',array_map(fn($t)=>['id'=>$t,'name'=>ucwords(str_replace('-',' ',$t))],$types),$type); reportFilters(in_array($type,['daily','monthly','term','year','method','receipts'],true)); ?><div class="form-actions"><button class="button primary">Generate report</button><a class="button" href="<?= e(url('reports')) ?>">Reset filters</a></div></form></section><section class="panel"><div class="section-heading"><div><h2><?= e(ucwords(str_replace('-',' ',$type))) ?> report</h2><p><?= e($school['name']) ?> · <?= e($school['currency']) ?> · <?= e(count($rows)) ?> rows</p></div><div class="no-print"><a class="button" href="<?= e('/?'.http_build_query(array_merge($_GET,['page'=>'reports','csv'=>1]))) ?>">Export CSV</a> <button class="button" data-print>Print / save PDF</button></div></div><div class="table-wrap"><table><thead><tr><?php foreach($headers as $h): ?><th><?= e($h) ?></th><?php endforeach ?></tr></thead><tbody><?php if(!$rows) emptyRow(count($headers),'No records match these filters.'); foreach($rows as $row): ?><tr><?php foreach($row as $value): ?><td><?= e($value) ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div></section>
